    static readonly List<DependencyObject> targets = new();
    public static event Action? LanguageChanged;
    public static string CurrentLanguage { get; private set; } = "en-US";
    public static IReadOnlyList<LanguageOption> Languages { get; } = new[] { new LanguageOption("en-US", "English"), new LanguageOption("vi-VN", "Tiếng Việt"), new LanguageOption("ko-KR", "한국어") };
    public static string Get(string key)
    {
        if (translations.TryGetValue(CurrentLanguage, out var lang) && lang.TryGetValue(key, out var value)) return value;
        return en.TryGetValue(key, out var fallback) ? fallback : key;
    }
    public static void Load()
    {
        try { var path = System.IO.Path.Combine(AppContext.BaseDirectory, "language.txt"); if (File.Exists(path)) CurrentLanguage = File.ReadAllText(path).Trim(); } catch { }
        if (!translations.ContainsKey(CurrentLanguage)) CurrentLanguage = "en-US";
    }
    public static void SetLanguage(string language)
    {
        if (!string.Equals(language, "en-US", StringComparison.OrdinalIgnoreCase) && !translations.ContainsKey(language)) language = "en-US";
        CurrentLanguage = language; try { File.WriteAllText(System.IO.Path.Combine(AppContext.BaseDirectory, "language.txt"), language); } catch { }
        foreach (var target in targets.ToArray()) Apply(target); LanguageChanged?.Invoke();
    }
    public static readonly DependencyProperty KeyProperty = DependencyProperty.RegisterAttached("Key", typeof(string), typeof(LocalizationManager), new PropertyMetadata(null, OnKeyChanged));
    public static void SetKey(DependencyObject obj, string value) { obj.SetValue(KeyProperty, value); }
    public static string GetKey(DependencyObject obj) => (string)obj.GetValue(KeyProperty);
    static void OnKeyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e) { if (!targets.Contains(d)) targets.Add(d); Apply(d); }
    static void Apply(DependencyObject d)
    {
        var key = GetKey(d); if (string.IsNullOrWhiteSpace(key)) return; var text = Get(key);
        switch (d) { case TextBlock t: t.Text = text; break; case TextBox t: t.Text = text; break; case Button b: b.Content = text; break; case CheckBox c: c.Content = text; break; case Label l: l.Content = text; break; case Window w: w.Title = text; break; case ToolTip tip: tip.Content = text; break; }
    }
}
